.investments USING btree (status);<br><br>CREATE INDEX loan_rate_schedule_household_id_idx ON public.loan_rate_schedule USING btree (household_id);<br><br>CREATE INDEX loans_household_id_idx ON public.loans USING btree (household_id);<br><br>CREATE INDEX loans_member_idx ON public.loans USING btree (member_id);<br><br>CREATE INDEX loans_status_idx ON public.loans USING btree (status);<br><br>CREATE INDEX members_household_id_idx ON public.members USING btree (household_id);<br><br>CREATE INDEX other_assets_household_id_idx ON public.other_assets USING btree (household_id);<br><br>CREATE INDEX other_assets_member_id_idx ON public.other_assets USING btree (member_id);<br><br>CREATE INDEX other_assets_member_idx ON public.other_assets USING btree (member_id);<br><br>CREATE INDEX other_assets_status_idx ON public.other_assets USING btree (status);<br><br>CREATE INDEX properties_household_id_idx ON public.properties USING btree (household_id);<br><br>CREATE INDEX properties_member_idx ON public.properties USING btree (member_id);<br><br>CREATE INDEX properties_status_idx ON public.properties USING btree (status);<br><br>CREATE INDEX property_rate_schedule_household_id_idx ON public.property_rate_schedule USING btree (household_id);<br><br>CREATE INDEX record_documents_entity_idx ON public.record_documents USING btree (entity_type, entity_id);<br><br>CREATE INDEX record_documents_household_id_idx ON public.record_documents USING btree (household_id);<br><br>CREATE INDEX record_history_entity_idx ON public.record_history USING btree (entity_type, entity_id);<br><br>CREATE INDEX record_history_household_id_idx ON public.record_history USING btree (household_id);<br><br>CREATE INDEX reminders_entity_idx ON public.reminders USING btree (entity_type, entity_id);<br><br>CREATE INDEX reminders_household_id_idx ON public.reminders USING btree (household_id);<br><br>CREATE INDEX reminders_remind_at_idx ON public.reminders USING btree (remind_at);<br><br>CREATE INDEX savings_accounts_household_id_idx ON public.savings_accounts USING btree (household_id);<br><br>CREATE INDEX savings_member_idx ON public.savings_accounts USING btree (member_id);<br><br>CREATE INDEX savings_status_idx ON public.savings_accounts USING btree (status);<br><br>CREATE OR REPLACE FUNCTION public.cascade_reminders_for_entity()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>  v_entity_type text;<br>BEGIN<br>  v_entity_type := TG_ARGV[0];<br><br>  DELETE FROM public.reminders r<br>  WHERE r.entity_type = v_entity_type<br>    AND r.entity_id = OLD.id<br>    AND r.household_id = OLD.household_id;<br><br>  RETURN OLD;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.cleanup_orphaned_household()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>declare<br>  remaining int;<br>begin<br>  select count(*) into remaining from household_users where household_id = old.household_id;<br>  if remaining = 0 then<br>    delete from app_settings where household_id = old.household_id;<br>    delete from gobag_items where household_id = old.household_id;<br>    delete from health_conditions where household_id = old.household_id;<br>    delete from inventory_folders where household_id = old.household_id;<br>    delete from inventory_items where household_id = old.household_id;<br>    delete from insurance_policies where household_id = old.household_id;<br>    delete from investments where household_id = old.household_id;<br>    delete from loan_rate_schedule where household_id = old.household_id;<br>    delete from loans where household_id = old.household_id;<br>    delete from members where household_id = old.household_id;<br>    delete from properties where household_id = old.household_id;<br>    delete from property_rate_schedule where household_id = old.household_id;<br>    delete from record_documents where household_id = old.household_id;<br>    delete from record_history where household_id = old.household_id;<br>    delete from reminders where household_id = old.household_id;<br>    delete from savings_accounts where household_id = old.household_id;<br>    delete from households where id = old.household_id;<br>  end if;<br>  return old;<br>end;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.current_household_id()<br> RETURNS uuid<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT COALESCE(<br>    NULLIF(auth.jwt() ->> 'household_id', '')::uuid,<br>    (<br>      SELECT hu.household_id<br>      FROM public.household_users hu<br>      WHERE hu.user_id = auth.uid()<br>      ORDER BY hu.created_at ASC<br>      LIMIT 1<br>    )<br>  );<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.current_user_household_ids()<br> RETURNS SETOF uuid<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT hu.household_id<br>  FROM public.household_users hu<br>  WHERE hu.user_id = auth.uid();<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.default_household_id()<br> RETURNS uuid<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT hu.household_id FROM public.household_users hu<br>  WHERE hu.user_id = auth.uid() LIMIT 1;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.enforce_household_storage_quota()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>declare<br>  v_household_id uuid;<br>  v_tier text;<br>  v_used bigint;<br>  v_incoming bigint;<br>  v_cap bigint := 10485760; -- 10 * 1024 * 1024 — matches the 10MB limit already shown in the app<br>begin<br>  if NEW.bucket_id not in ('vault-docs', 'inventory-photos') then<br>    return NEW;<br>  end if;<br><br>  v_household_id := split_part(NEW.name, '/', 1)::uuid;<br>  v_incoming := coalesce((NEW.metadata->>'size')::bigint, 0);<br><br>  select storage_tier, storage_bytes_used into v_tier, v_used<br>  from households where id = v_household_id;<br><br>  if v_tier = 'premium' then<br>    return NEW;<br>  end if;<br><br>  if coalesce(v_used, 0) + v_incoming > v_cap then<br>    raise exception 'storage_quota_exceeded: household % is at its free storage limit', v_household_id;<br>  end if;<br><br>  return NEW;<br>end;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.ensure_household_app_settings()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>BEGIN<br>  INSERT INTO public.app_settings (household_id, family_name)<br>  VALUES (NEW.id, COALESCE(NULLIF(trim(NEW.name), ''), 'Our Family'))<br>  ON CONFLICT (household_id) DO NOTHING;<br><br>  RETURN NEW;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.ensure_household_default_member()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>BEGIN<br>  IF NOT EXISTS (<br>    SELECT 1<br>    FROM public.members m<br>    WHERE m.household_id = NEW.id<br>  ) THEN<br>    INSERT INTO public.members (<br>      household_id,<br>      name,<br>      short_name,<br>      color,<br>      sort_order,<br>      emoji<br>    )<br>    VALUES (<br>      NEW.id,<br>      'Default Member',<br>      'ME',<br>      'hsl(221 83% 53%)',<br>      0,<br>      '👤'<br>    );<br>  END IF;<br><br>  RETURN NEW;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.handle_new_auth_user()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>DECLARE<br>  v_household_id uuid;<br>  v_household_name text;<br>  v_invite record;<br>BEGIN<br>  INSERT INTO public.user_profiles (user_id, email)<br>  VALUES (NEW.id, NEW.email)<br>  ON CONFLICT (user_id) DO NOTHING;<br><br>  -- NEW: if this brand-new signup has a pending household invite waiting<br>  -- for their exact email, join THAT household as the invited role,<br>  -- instead of falling through to "create them a fresh household."<br>  -- This is what was missing — every new signup got its own household<br>  -- regardless of any invite, because this check never existed.<br>  SELECT * INTO v_invite<br>  FROM public.household_invites<br>  WHERE lower(invited_email) = lower(NEW.email)<br>    AND accepted_at IS NULL<br>    AND cancelled_at IS NULL<br>    AND expires_at > now()<br>  ORDER BY created_at ASC<br>  LIMIT 1;<br><br>  IF v_invite.id IS NOT NULL THEN<br>    INSERT INTO public.household_users (household_id, user_id, role, invited_by)<br>    VALUES (v_invite.household_id, NEW.id, v_invite.role, v_invite.invited_by_user_id)<br>    ON CONFLICT (household_id, user_id) DO NOTHING;<br><br>    UPDATE public.household_invites<br>    SET accepted_at = now(), accepted_by_user_id = NEW.id<br>    WHERE id = v_invite.id;<br><br>    RETURN NEW;<br>  END IF;<br><br>  v_household_name := COALESCE(<br>    NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), ''),<br>    NULLIF(trim(NEW.raw_user_meta_data ->> 'name'), ''),<br>    CONCAT(split_part(COALESCE(NEW.email, 'user'), '@', 1), '''s Household')<br>  );<br>  INSERT INTO public.households (name)<br>  VALUES (v_household_name)<br>  RETURNING id INTO v_household_id;<br>  INSERT INTO public.household_users (household_id, user_id, role)<br>  VALUES (v_household_id, NEW.id, 'owner')<br>  ON CONFLICT (household_id, user_id) DO NOTHING;<br>  RETURN NEW;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.has_advisor_access(target_household_id uuid, category text)<br> RETURNS boolean<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT EXISTS (<br>    SELECT 1 FROM advisor_household_links l<br>    WHERE l.household_id = target_household_id<br>      AND l.advisor_user_id = auth.uid()<br>      AND l.status = 'active'<br>      AND l.consent_renewed_at > (now() - interval '365 days')<br>      AND (<br>        (category = 'insurance' AND l.can_view_insurance)<br>        OR (category = 'investments' AND l.can_view_investments)<br>        OR (category = 'networth_summary' AND l.can_view_networth_summary)<br>      )<br>  );<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.has_advisor_access(target_household_id uuid, target_member_id uuid, category text)<br> RETURNS boolean<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  select exists (<br>    select 1 from public.advisor_household_links l<br>    where l.household_id = target_household_id<br>      and l.advisor_user_id = auth.uid()<br>      and l.status = 'active'<br>      and l.consent_renewed_at > (now() - interval '365 days')<br>      and (<br>        (category = 'insurance' and l.can_view_insurance)<br>        or (category = 'investments' and l.can_view_investments)<br>        or (category = 'networth_summary' and l.can_view_networth_summary)<br>        or (category = 'property' and l.can_view_property)<br>        or (category = 'loans' and l.can_view_loans)<br>      )<br>      and exists (<br>        select 1 from public.advisor_link_members alm<br>        where alm.link_id = l.id<br>          and (target_member_id is null or alm.member_id = target_member_id)<br>      )<br>  );<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.increment_household_storage(p_household_id uuid, p_delta bigint)<br> RETURNS void<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>begin<br>  if not is_household_member(p_household_id) then<br>    raise exception 'not a member of this household';<br>  end if;<br><br>  update households<br>  set storage_bytes_used = (<br>    select coalesce(sum((o.metadata->>'size')::bigint), 0)<br>    from storage.objects o<br>    where o.bucket_id in ('vault-docs', 'inventory-photos')<br>      and o.name like p_household_id::text \|\| '/%'<br>  )<br>  where id = p_household_id;<br>end;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.is_household_editor(target_household_id uuid)<br> RETURNS boolean<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT EXISTS (<br>    SELECT 1<br>    FROM public.household_users hu<br>    WHERE hu.household_id = target_household_id<br>      AND hu.user_id = auth.uid()<br>      AND hu.role IN ('owner', 'member')<br>  );<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.is_household_member(target_household_id uuid)<br> RETURNS boolean<br> LANGUAGE sql<br> STABLE<br>AS $function$<br>  SELECT EXISTS (<br>    SELECT 1<br>    FROM public.household_users hu<br>    WHERE hu.household_id = target_household_id<br>      AND hu.user_id = auth.uid()<br>  );<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.log_financial_audit()<br> RETURNS trigger<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public'<br>AS $function$<br>declare<br>  v_household_id uuid;<br>  v_row jsonb;<br>  v_old jsonb;<br>  v_new jsonb;<br>  v_changed_fields text[];<br>  v_key text;<br>begin<br>  v_old := case when TG_OP in ('UPDATE', 'DELETE') then to_jsonb(OLD) else null end;<br>  v_new := case when TG_OP in ('UPDATE', 'INSERT') then to_jsonb(NEW) else null end;<br>  v_row := coalesce(v_new, v_old);<br><br>  -- household_id lives directly on some of these tables (investments, savings_accounts,<br>  -- loans, other_assets) but NOT on insurance_policies or properties (member_id only,<br>  -- verified against the actual schema, not assumed) — derive it via member_id there instead.<br>  if v_row ? 'household_id' then<br>    v_household_id := (v_row ->> 'household_id')::uuid;<br>  elsif v_row ? 'member_id' and (v_row ->> 'member_id') is not null then<br>    select household_id into v_household_id from members where id = (v_row ->> 'member_id')::uuid;<br>  end if;<br><br>  if TG_OP = 'UPDATE' then<br>    select array_agg(k) into v_changed_fields<br>    from jsonb_each(v_new) as n(k, val)<br>    where n.val is distinct from (v_old -> n.k)<br>      and n.k not in ('updated_at'); -- pure timestamp bumps aren't a meaningful "edit"<br>    if v_changed_fields is null then<br>      return NEW; -- nothing meaningful changed — don't log a no-op<br>    end if;<br>  end if;<br><br>  insert into audit_log (household_id, table_name, record_id, action, changed_by, changed_fields, old_data, new_data)<br>  values (<br>    v_household_id,<br>    TG_TABLE_NAME,<br>    (v_row ->> 'id')::uuid,<br>    TG_OP,<br>    auth.uid(),<br>    v_changed_fields,<br>    v_old,<br>    v_new<br>  );<br><br>  return coalesce(NEW, OLD);<br>end;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.set_credit_cards_updated_at()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>begin<br>  new.updated_at = now();<br>  return new;<br>end;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.set_updated_at()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>begin<br>  new.updated_at = now();<br>  return new;<br>end;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.share_household_by_email(p_household_id uuid, p_email text, p_role text DEFAULT 'member'::text)<br> RETURNS uuid<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public', 'auth'<br>AS $function$<br>DECLARE<br>  v_actor uuid := auth.uid();<br>  v_target_user_id uuid;<br>  v_email text := lower(trim(COALESCE(p_email, '')));<br>  v_role text := lower(trim(COALESCE(p_role, 'member')));<br>BEGIN<br>  IF v_actor IS NULL THEN<br>    RAISE EXCEPTION 'Not authenticated.';<br>  END IF;<br><br>  IF p_household_id IS NULL THEN<br>    RAISE EXCEPTION 'Household is required.';<br>  END IF;<br><br>  IF v_email = '' THEN<br>    RAISE EXCEPTION 'Email is required.';<br>  END IF;<br><br>  IF v_role NOT IN ('member', 'viewer') THEN<br>    RAISE EXCEPTION 'Role must be member or viewer.';<br>  END IF;<br><br>  IF NOT EXISTS (<br>    SELECT 1<br>    FROM public.household_users hu<br>    WHERE hu.household_id = p_household_id<br>      AND hu.user_id = v_actor<br>      AND hu.role = 'owner'<br>  ) THEN<br>    RAISE EXCEPTION 'Only household owners can share access.';<br>  END IF;<br><br>  SELECT u.id<br>  INTO v_target_user_id<br>  FROM auth.users u<br>  WHERE lower(u.email) = v_email<br>  LIMIT 1;<br><br>  IF v_target_user_id IS NULL THEN<br>    RAISE EXCEPTION 'No account found for that email yet. Ask them to sign in first, then share again.';<br>  END IF;<br><br>  INSERT INTO public.household_users (household_id, user_id, role, invited_by)<br>  VALUES (p_household_id, v_target_user_id, v_role, v_actor)<br>  ON CONFLICT (household_id, user_id)<br>  DO UPDATE SET<br>    role = EXCLUDED.role,<br>    invited_by = EXCLUDED.invited_by;<br><br>  RETURN v_target_user_id;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.sync_lrs_household_id()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>  IF NEW.household_id IS NULL THEN<br>    SELECT l.household_id INTO NEW.household_id<br>    FROM public.loans l<br>    WHERE l.id = NEW.loan_id;<br>  END IF;<br><br>  IF NEW.household_id IS NULL THEN<br>    NEW.household_id := public.default_household_id();<br>  END IF;<br><br>  RETURN NEW;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.sync_prs_household_id()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>BEGIN<br>  IF NEW.household_id IS NULL THEN<br>    SELECT p.household_id INTO NEW.household_id<br>    FROM public.properties p<br>    WHERE p.id = NEW.property_id;<br>  END IF;<br><br>  IF NEW.household_id IS NULL THEN<br>    NEW.household_id := public.default_household_id();<br>  END IF;<br><br>  RETURN NEW;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.transfer_household_ownership_by_email(p_household_id uuid, p_email text)<br> RETURNS void<br> LANGUAGE plpgsql<br> SECURITY DEFINER<br> SET search_path TO 'public', 'auth'<br>AS $function$<br>DECLARE<br>  v_actor uuid := auth.uid();<br>  v_target_user_id uuid;<br>  v_email text := lower(trim(COALESCE(p_email, '')));<br>BEGIN<br>  IF v_actor IS NULL THEN<br>    RAISE EXCEPTION 'Not authenticated.';<br>  END IF;<br><br>  IF p_household_id IS NULL THEN<br>    RAISE EXCEPTION 'Household is required.';<br>  END IF;<br><br>  IF v_email = '' THEN<br>    RAISE EXCEPTION 'Email is required.';<br>  END IF;<br><br>  IF NOT EXISTS (<br>    SELECT 1<br>    FROM public.household_users hu<br>    WHERE hu.household_id = p_household_id<br>      AND hu.user_id = v_actor<br>      AND hu.role = 'owner'<br>  ) THEN<br>    RAISE EXCEPTION 'Only household owners can transfer ownership.';<br>  END IF;<br><br>  SELECT u.id<br>  INTO v_target_user_id<br>  FROM auth.users u<br>  WHERE lower(u.email) = v_email<br>  LIMIT 1;<br><br>  IF v_target_user_id IS NULL THEN<br>    RAISE EXCEPTION 'No account found for that email.';<br>  END IF;<br><br>  IF v_target_user_id = v_actor THEN<br>    RAISE EXCEPTION 'You are already the owner.';<br>  END IF;<br><br>  IF NOT EXISTS (<br>    SELECT 1<br>    FROM public.household_users hu<br>    WHERE hu.household_id = p_household_id<br>      AND hu.user_id = v_target_user_id<br>  ) THEN<br>    RAISE EXCEPTION 'Target user must already be a member of this household.';<br>  END IF;<br><br>  -- Enforce a single owner after transfer.<br>  UPDATE public.household_users<br>  SET role = 'member'<br>  WHERE household_id = p_household_id<br>    AND role = 'owner';<br><br>  UPDATE public.household_users<br>  SET role = 'owner'<br>  WHERE household_id = p_household_id<br>    AND user_id = v_target_user_id;<br>END;<br>$function$<br>;<br><br>CREATE OR REPLACE FUNCTION public.validate_reminder_target()<br> RETURNS trigger<br> LANGUAGE plpgsql<br>AS $function$<br>DECLARE<br>  v_exists boolean := false;<br>BEGIN<br>  IF NEW.entity_type IS NULL OR NEW.entity_id IS NULL THEN<br>    RAISE EXCEPTION 'reminders.entity_type and reminders.entity_id are required';<br>  END IF;<br><br>  IF NEW.household_id IS NULL THEN<br>    RAISE EXCEPTION 'reminders.household_id is required for entity integrity checks';<br>  END IF;<br><br>  IF NEW.entity_type = 'property' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.properties p<br>      WHERE p.id = NEW.entity_id<br>        AND p.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'loan' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.loans l<br>      WHERE l.id = NEW.entity_id<br>        AND l.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'insurance' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.insurance_policies i<br>      WHERE i.id = NEW.entity_id<br>        AND i.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'investment' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.investments i<br>      WHERE i.id = NEW.entity_id<br>        AND i.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'savings' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.savings_accounts s<br>      WHERE s.id = NEW.entity_id<br>        AND s.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'health' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.health_conditions h<br>      WHERE h.id = NEW.entity_id<br>        AND h.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'inventory' THEN<br>    SELECT EXISTS (<br>      SELECT 1 FROM public.inventory_items ii<br>      WHERE ii.id = NEW.entity_id<br>        AND ii.household_id = NEW.household_id<br>    ) INTO v_exists;<br><br>  ELSIF NEW.entity_type = 'other_asset' THEN<br>    IF to_regclass('public.other_assets') IS NULL THEN<br>      RAISE EXCEPTION 'entity_type other_asset is not available: public.other_assets does not exist';<br>    END IF;<br><br>    EXECUTE<br>      'SELECT EXISTS (<br>         SELECT 1 FROM public.other_assets oa<br>         WHERE oa.id = $1<br>           AND oa.household_id = $2<br>       )'<br>    INTO v_exists<br>    USING NEW.entity_id, NEW.household_id;<br><br>  ELSE<br>    RAISE EXCEPTION 'Unsupported reminders.entity_type: %', NEW.entity_type;<br>  END IF;<br><br>  IF NOT v_exists THEN<br>    RAISE EXCEPTION<br>      'Invalid reminder target: type=% id=% household_id=%',<br>      NEW.entity_type,<br>      NEW.entity_id,<br>      NEW.household_id;<br>  END IF;<br><br>  RETURN NEW;<br>END;<br>$function$<br>;<br><br>REVOKE ALL ON FUNCTION public.cascade_reminders_for_entity() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.cascade_reminders_for_entity() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.cascade_reminders_for_entity() TO anon;<br>GRANT EXECUTE ON FUNCTION public.cascade_reminders_for_entity() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.cascade_reminders_for_entity() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.cleanup_orphaned_household() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.cleanup_orphaned_household() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.cleanup_orphaned_household() TO anon;<br>GRANT EXECUTE ON FUNCTION public.cleanup_orphaned_household() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.cleanup_orphaned_household() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.current_household_id() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.current_household_id() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.current_household_id() TO anon;<br>GRANT EXECUTE ON FUNCTION public.current_household_id() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.current_household_id() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.current_user_household_ids() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.current_user_household_ids() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.current_user_household_ids() TO anon;<br>GRANT EXECUTE ON FUNCTION public.current_user_household_ids() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.current_user_household_ids() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.default_household_id() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.default_household_id() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.default_household_id() TO anon;<br>GRANT EXECUTE ON FUNCTION public.default_household_id() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.default_household_id() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.enforce_household_storage_quota() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.enforce_household_storage_quota() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.enforce_household_storage_quota() TO anon;<br>GRANT EXECUTE ON FUNCTION public.enforce_household_storage_quota() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.enforce_household_storage_quota() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.ensure_household_app_settings() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_app_settings() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_app_settings() TO anon;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_app_settings() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_app_settings() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.ensure_household_default_member() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_default_member() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_default_member() TO anon;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_default_member() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.ensure_household_default_member() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.handle_new_auth_user() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.handle_new_auth_user() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.handle_new_auth_user() TO anon;<br>GRANT EXECUTE ON FUNCTION public.handle_new_auth_user() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.handle_new_auth_user() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.has_advisor_access(target_household_id uuid, category text) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, category text) TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, category text) TO anon;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, category text) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, category text) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.has_advisor_access(target_household_id uuid, target_member_id uuid, category text) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, target_member_id uuid, category text) TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, target_member_id uuid, category text) TO anon;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, target_member_id uuid, category text) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.has_advisor_access(target_household_id uuid, target_member_id uuid, category text) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.increment_household_storage(p_household_id uuid, p_delta bigint) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.increment_household_storage(p_household_id uuid, p_delta bigint) TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.increment_household_storage(p_household_id uuid, p_delta bigint) TO anon;<br>GRANT EXECUTE ON FUNCTION public.increment_household_storage(p_household_id uuid, p_delta bigint) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.increment_household_storage(p_household_id uuid, p_delta bigint) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.is_household_editor(target_household_id uuid) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.is_household_editor(target_household_id uuid) TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.is_household_editor(target_household_id uuid) TO anon;<br>GRANT EXECUTE ON FUNCTION public.is_household_editor(target_household_id uuid) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.is_household_editor(target_household_id uuid) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.is_household_member(target_household_id uuid) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.is_household_member(target_household_id uuid) TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.is_household_member(target_household_id uuid) TO anon;<br>GRANT EXECUTE ON FUNCTION public.is_household_member(target_household_id uuid) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.is_household_member(target_household_id uuid) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.log_financial_audit() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.log_financial_audit() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.log_financial_audit() TO anon;<br>GRANT EXECUTE ON FUNCTION public.log_financial_audit() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.log_financial_audit() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.set_credit_cards_updated_at() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.set_credit_cards_updated_at() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.set_credit_cards_updated_at() TO anon;<br>GRANT EXECUTE ON FUNCTION public.set_credit_cards_updated_at() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.set_credit_cards_updated_at() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.set_updated_at() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.set_updated_at() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.set_updated_at() TO anon;<br>GRANT EXECUTE ON FUNCTION public.set_updated_at() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.set_updated_at() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.share_household_by_email(p_household_id uuid, p_email text, p_role text) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.share_household_by_email(p_household_id uuid, p_email text, p_role text) TO anon;<br>GRANT EXECUTE ON FUNCTION public.share_household_by_email(p_household_id uuid, p_email text, p_role text) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.share_household_by_email(p_household_id uuid, p_email text, p_role text) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.sync_lrs_household_id() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.sync_lrs_household_id() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.sync_lrs_household_id() TO anon;<br>GRANT EXECUTE ON FUNCTION public.sync_lrs_household_id() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.sync_lrs_household_id() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.sync_prs_household_id() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.sync_prs_household_id() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.sync_prs_household_id() TO anon;<br>GRANT EXECUTE ON FUNCTION public.sync_prs_household_id() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.sync_prs_household_id() TO service_role;<br><br>REVOKE ALL ON FUNCTION public.transfer_household_ownership_by_email(p_household_id uuid, p_email text) FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.transfer_household_ownership_by_email(p_household_id uuid, p_email text) TO anon;<br>GRANT EXECUTE ON FUNCTION public.transfer_household_ownership_by_email(p_household_id uuid, p_email text) TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.transfer_household_ownership_by_email(p_household_id uuid, p_email text) TO service_role;<br><br>REVOKE ALL ON FUNCTION public.validate_reminder_target() FROM PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.validate_reminder_target() TO PUBLIC;<br>GRANT EXECUTE ON FUNCTION public.validate_reminder_target() TO anon;<br>GRANT EXECUTE ON FUNCTION public.validate_reminder_target() TO authenticated;<br>GRANT EXECUTE ON FUNCTION public.validate_reminder_target() TO service_role;<br><br>CREATE OR REPLACE VIEW public.advisor_client_summary_view AS<br> SELECT h.id AS household_id,<br>    h.name AS household_name,<br>    'insurance'::text AS category,<br>    i.id AS record_id,<br>    i.name AS record_name,<br>    i.category AS insurance_category,<br>    i.premium,<br>    i.frequency,<br>    i.start_date,<br>    i.end_date,<br>    i.sum_assured,<br>    i.currency,<br>    i.updated_at AS last_updated,<br>    i.is_giro,<br>    i.member_id,<br>    m.name AS member_name<br>   FROM insurance_policies i<br>     JOIN households h ON h.id = i.household_id<br>     LEFT JOIN members m ON m.id = i.member_id<br>  WHERE has_advisor_access(i.household_id, i.member_id, 'insurance'::text) AND NOT i.hidden_from_advisors<br>UNION ALL<br> SELECT h.id AS household_id,<br>    h.name AS household_name,<br>    'investments'::text AS category,<br>    inv.id AS record_id,<br>    inv.name AS record_name,<br>    inv.group_name AS insurance_category,<br>    inv.premium_amount AS premium,<br>    inv.premium_frequency AS frequency,<br>    inv.premium_start_date AS start_date,<br>    inv.premium_end_date AS end_date,<br>    inv.current_value AS sum_assured,<br>    inv.currency,<br>    inv.updated_at AS last_updated,<br>    false AS is_giro,<br>    inv.member_id,<br>    m.name AS member_name<br>   FROM investments inv<br>     JOIN households h ON h.id = inv.household_id<br>     LEFT JOIN members m ON m.id = inv.member_id<br>  WHERE has_advisor_access(inv.household_id, inv.member_id, 'investments'::text) AND NOT inv.hidden_from_advisors<br>UNION ALL<br> SELECT h.id AS household_id,<br>    h.name AS household_name,<br>    'property'::text AS category,<br>    p.id AS record_id,<br>    p.name AS record_name,<br>        CASE p.purpose<br>            WHEN 'capital_growth'::text THEN 'Capital Growth'::text<br>            WHEN 'rental_yield'::text THEN 'Rental Yield'::text<br>            WHEN 'own_home'::text THEN 'Own Home'::text<br>            ELSE 'Other'::text<br>        END AS insurance_category,<br>    NULL::numeric AS premium,<br>    NULL::text AS frequency,<br>    NULL::date AS start_date,<br>    NULL::date AS end_date,<br>    p.current_value AS sum_assured,<br>    p.currency,<br>    p.updated_at AS last_updated,<br>    false AS is_giro,<br>    p.member_id,<br>    m.name AS member_name<br>   FROM properties p<br>     JOIN households h ON h.id = p.household_id<br>     LEFT JOIN members m ON m.id = p.member_id<br>  WHERE has_advisor_access(p.household_id, p.member_id, 'property'::text) AND NOT p.hidden_from_advisors<br>UNION ALL<br> SELECT h.id AS household_id,<br>    h.name AS household_name,<br>    'loans'::text AS category,<br>    l.id AS record_id,<br>    (COALESCE(NULLIF(l.purpose, ''::text), 'Loan'::text) \|\| ' · '::text) \|\| l.bank AS record_name,<br>    COALESCE(NULLIF(l.purpose, ''::text), 'Other'::text) AS insurance_category,<br>    NULL::numeric AS premium,<br>    NULL::text AS frequency,<br>    NULL::date AS start_date,<br>    NULL::date AS end_date,<br>    l.balance AS sum_assured,<br>    l.currency,<br>    l.updated_at AS last_updated,<br>    false AS is_giro,<br>    l.member_id,<br>    m.name AS member_name<br>   FROM loans l<br>     JOIN households h ON h.id = l.household_id<br>     LEFT JOIN members m ON m.id = l.member_id<br>  WHERE has_advisor_access(l.household_id, l.member_id, 'loans'::text) AND NOT l.hidden_from_advisors;<br><br>CREATE OR REPLACE VIEW public.advisor_networth_components_view AS<br> SELECT properties.household_id,<br>    'property'::text AS source_type,<br>    properties.current_value AS amount,<br>    properties.currency,<br>    NULL::text AS account_type,<br>    properties.member_id<br>   FROM properties<br>  WHERE has_advisor_access(properties.household_id, properties.member_id, 'networth_summary'::text)<br>UNION ALL<br> SELECT investments.household_id,<br>    'investment'::text AS source_type,<br>    investments.current_value AS amount,<br>    investments.currency,<br>    NULL::text AS account_type,<br>    investments.member_id<br>   FROM investments<br>  WHERE has_advisor_access(investments.household_id, investments.member_id, 'networth_summary'::text)<br>UNION ALL<br> SELECT savings_accounts.household_id,<br>    'savings'::text AS source_type,<br>    savings_accounts.balance AS amount,<br>    savings_accounts.currency,<br>    savings_accounts.account_type,<br>    savings_accounts.member_id<br>   FROM savings_accounts<br>  WHERE has_advisor_access(savings_accounts.household_id, savings_accounts.member_id, 'networth_summary'::text)<br>UNION ALL<br> SELECT other_assets.household_id,<br>    'other_asset'::text AS source_type,<br>    other_assets.estimated_value AS amount,<br>    other_assets.currency,<br>    NULL::text AS account_type,<br>    other_assets.member_id<br>   FROM other_assets<br>  WHERE has_advisor_access(other_assets.household_id, other_assets.member_id, 'networth_summary'::text)<br>UNION ALL<br> SELECT insurance_policies.household_id,<br>    'insurance_surrender'::text AS source_type,<br>        CASE<br>            WHEN insurance_policies.surrender_value_date IS NULL OR insurance_policies.surrender_value_date <= CURRENT_DATE THEN insurance_policies.surrender_value<br>            ELSE 0::numeric<br>        END AS amount,<br>    insurance_policies.currency,<br>    NULL::text AS account_type,<br>    insurance_policies.member_id<br>   FROM insurance_policies<br>  WHERE has_advisor_access(insurance_policies.household_id, insurance_policies.member_id, 'networth_summary'::text)<br>UNION ALL<br> SELECT loans.household_id,<br>    'loan'::text AS source_type,<br>    loans.balance AS amount,<br>    loans.currency,<br>    NULL::text AS account_type,<br>    loans.member_id<br>   FROM loans<br>  WHERE has_advisor_access(loans.household_id, loans.member_id, 'networth_summary'::text)<br>UNION ALL<br> SELECT properties.household_id,<br>    'property_mortgage'::text AS source_type,<br>    properties.mortgage_balance AS amount,<br>    properties.currency,<br>    NULL::text AS account_type,<br>    properties.member_id<br>   FROM properties<br>  WHERE has_advisor_access(properties.household_id, properties.member_id, 'networth_summary'::text) AND properties.mortgage_balance IS NOT NULL AND NOT (EXISTS ( SELEC